head.script:
scwin.decl_seq = frame.opener.key_seq;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        await scwin.setCode();
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.initPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30411.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30411.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30411.btn_Cancel_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30411.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
        await $c.win.alert(msg);
        const fr_fn_Search = $c.frame.path("../").fn_Search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30411.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Delete_onclick = function() {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30411.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「search」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = function() {
    try {
        $c.lc.fn_PopFindZipCd();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30411.btn_search_onclick" });
    }
};

/**
 * @method
 * @name grd_FILE_LIST_OnClick
 * @description grd_FILE_LIST 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_FILE_LIST_OnClick = function(row, colid) {
    try {
        scwin.downLoad(row, colid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30411.grd_FILE_LIST_OnClick" });
    }
};

/**
 * @method
 * @name btn_AddRow_onclick
 * @description 「추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_AddRow_onclick = async function() {
    try {
        if (dts_FILE_LIST.getRowCount() === 5) {
            await $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
        dts_FILE_LIST.insertRow();
        btn_File.open();
        if (btn_File.getValue() !== "") {
            dts_FILE_LIST.setCellData(dts_FILE_LIST.getRowPosition(), "ATTACH_FILE_NM", btn_File.getValue());
            dts_FILE_LIST.setCellData(dts_FILE_LIST.getRowPosition(), "FILEURL", btn_File.getValue());
        } else {
            dts_FILE_LIST.removeRow(dts_FILE_LIST.getRowPosition());
        }
        btn_File.setValue("");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30411.btn_AddRow_onclick" });
    }
};

/**
 * @method
 * @name btn_DelRow_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_DelRow_onclick = function() {
    try {
        dts_FILE_LIST.removeRow(dts_FILE_LIST.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30411.btn_DelRow_onclick" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_ABBRV);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30411.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    try {
        txb_DECL_SEQ.setValue(txb_DECL_SEQ.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30411.dts_MASTER_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setNewMode
 * @description set New Mode 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setNewMode = async function() {
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_MASTER.insertRow();
    const sbmOptions2 = {
        id : "sbm_dts_FILE_LIST",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_FILE_LIST=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_DECLR_TP",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DECLR_TP=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name readDecl
 * @description read Decl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readDecl = async function() {
    url += "&DECL_SEQ=" + scwin.decl_seq;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/UnfaithfulDesignReport.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&DECL_SEQ=" + scwin.decl_seq;
    const sbmOptions2 = {
        id : "sbm_dts_FILE_LIST",
        action : "/UnfaithfulDesignReport.do",
        ref : "",
        target : "dts_FILE_LIST=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    txb_ISUR_CD.hide();
    txb_DECL_SEQ.hide();
    if (scwin.decl_seq === '') {
        // 신규작성
        await scwin.setNewMode();
        rdo_ATTACH_DOC_REG_TP_CD.setValue("01");
        btn_Delete.hide();
    } else {
        // 수정화면
        await scwin.readDecl();
        img_com_srch.hide();
        btn_Delete.hide();
        btn_Save.hide();
        btn_AddRow.hide();
        btn_DelRow.hide();
        txb_DECLR_NM.setReadOnly(true);
        txb_DECLR_NM.style.backgroundColor = '#b9d4f7';
        txb_BIRTHDD.setReadOnly(true);
        txb_BIRTHDD.style.backgroundColor = '#b9d4f7';
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const birthdd = txb_BIRTHDD.getValue();
    if (txb_DECLR_NM.getValue() === "") {
        await $c.win.alert("[성명]을 입력하세요.");
        return false;
    }
    if (birthdd === "") {
        await $c.win.alert("[생년월일]을 입력하세요.");
        return false;
    } else {
        if (BIRTHDD.length !== 8) {
            await $c.win.alert("생년월일을 8자리로 입력해주세요. ex)19800312");
            return false;
        }
    }
    if ($c.stf.IsValidEmail(txb_DECLR_EMAIL.getValue()) === false) {
        await $c.win.alert("[이메일] 정확하지 않습니다.");
        txb_DECLR_EMAIL.focus();
        return false;
    }
    if (txb_DECLR_TEL_NO.getValue() === "") {
        await $c.win.alert("[연락처]를 입력하세요.");
        txb_DECLR_TEL_NO.focus();
        return false;
    }
    if (txb_DECLR_FAX_NO.getValue() === "") {
        await $c.win.alert("[팩스번호]를 입력하세요.");
        txb_DECLR_FAX_NO.focus();
        return false;
    }
    if (txb_ZIPCD.getValue() === "") {
        await $c.win.alert("[주소]를 입력하세요.");
        txb_ZIPCD.focus();
        return false;
    }
    if (rdo_DECLR_TP_CD.getValue() === "") {
        await $c.win.alert("[신고자구분]를 선택하세요.");
        rdo_DECLR_TP_CD.focus();
        return false;
    }
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[종목]을 입력하세요.");
        return false;
    }
    if (txa_DECL_CONTN.getValue() === "") {
        await $c.win.alert("[위반내용]을 입력하세요.");
        return false;
    }
    if (rdo_OTHRINST_DECL_YN.getValue() === "") {
        await $c.win.alert("[동건의 타부서(타기관포함)신고여부]를 선택하세요.");
        rdo_OTHRINST_DECL_YN.focus();
        return false;
    }
    if (rdo_RECENT_YY3_RWD_YN.getValue() === "") {
        await $c.win.alert("[동건의신고로인한타부서 포상여부]를 선택하세요.");
        rdo_RECENT_YY3_RWD_YN.focus();
        return false;
    }
    /*
    if(decl_seq == '') {
    	if (getObjectValue(txb_AUTH_YN) != "Y") {
    		alert("실명인증을 하셔야 합니다.");return false;
    	}
    }
     */
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (window.confirm("[저장]하시겠습니까?")) {
            gLastJob = "저장";
            let url = "/UnfaithfulDesignReport.do?method=saveNfaithDsclDecl" + "&SCREN_ID=" + "ULDSTF30411.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER, I:pFile=dts_FILE_LIST)";
            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name downLoad
 * @description down Load 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.downLoad = function(row, colid) {
    const filename = dts_FILE_LIST.getCellData(row, "ATTACH_FILE_NM");
    if (filename === "") return;
    if (colid === "ATTACH_FILE_NM") {
        const DECL_SEQ = dts_FILE_LIST.getCellData(row, "DECL_SEQ");
        const DECL_ATTACH_SEQ = dts_FILE_LIST.getCellData(row, "DECL_ATTACH_SEQ");
        let url = "/filedownload.do?gubun=22";
        url += "&decl_seq=" + DECL_SEQ;
        url += "&decl_attach_seq=" + DECL_ATTACH_SEQ;
        location.href = url;
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {void}
 * @hidden N
 */
scwin.delete = function() {
    if (window.confirm("[삭제]하시겠습니까?")) {
        txb_DECLR_NM.setValue("");
        gLastJob = "삭제";
        let url = "/UnfaithfulDesignReport.do?method=deleteNfaithDsclDecl" + "&SCREN_ID=" + "ULDSTF30411.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name realNameCert
 * @description 실명인증하는데 사용한다. 처리에서는 실명을 빼기로 해서 여기에서는 사용하지 않는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.realNameCert = async function() {
    const nm = txb_DECLR_NM.getValue();
    const reg_no = txb_RESD_REG_NO.getValue();
    if (nm === '') {
        await $c.win.alert("이름을 입력하셔야 합니다.");
        return;
    }
    if (reg_no === '') {
        await $c.win.alert("주민등록번호를 입력하셔야 합니다.");
        return;
    }
    let url = "/dsclinfo/ULDSTF30412.jsp?NM=" + nm + "&REG_NO=" + reg_no;
    const winTitle = "신규";
    await $c.frame.CreateFrame("ULDSTF30412", url, winTitle, 10, 10, 100, 200, "window", 0, 0, true);
};

/**
 * @method
 * @name auth
 * @description auth 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.auth = async function() {
    await $c.win.alert("fn_auth");
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    txb_ZIPCD.setValue(arrPar[0]);
    txb_ADDR.setValue(arrPar[1]);
};
